package com.example.solarfarm.domain;

import jakarta.persistence.*; import java.time.Instant; import com.example.solarfarm.domain.Enums.FaultEventStatus;
@Entity @Table(name="fault_events") public class FaultEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="event_id",nullable=false,unique=true) private String eventId; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="panel_id") private Panel panel; @Column(name="start_time",nullable=false) private Instant startTime; @Column(name="end_time",nullable=false) private Instant endTime; @Column(name="fault_type",nullable=false) private String faultType; @Column(nullable=false) private double severity; @Enumerated(EnumType.STRING) @Column(nullable=false) private FaultEventStatus status; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); protected FaultEvent(){} public FaultEvent(String e,Panel p,Instant s,Instant end,String f,double sev){eventId=e;panel=p;startTime=s;endTime=end;faultType=f;severity=sev;status=FaultEventStatus.ACTIVE;} public String getEventId(){return eventId;} public Panel getPanel(){return panel;} public Instant getStartTime(){return startTime;} public Instant getEndTime(){return endTime;} public String getFaultType(){return faultType;} public double getSeverity(){return severity;} public FaultEventStatus getStatus(){return status;} }
